"""Row merging.

R5 — Duplicate-SKU transformation

`merge_rows(rows)` must combine repeated SKUs by summing quantities, return one row per SKU in first-occurrence SKU order, and keep the labels tuple from the first row for each SKU.
"""

from .model import InventoryRow


def merge_rows(rows):
    order = []
    merged = {}
    for row in rows:
        if row.sku not in merged:
            order.append(row.sku)
            merged[row.sku] = row
        else:
            first = merged[row.sku]
            merged[row.sku] = InventoryRow(
                row.sku,
                first.quantity + row.quantity,
                first.labels,
            )
    return [merged[sku] for sku in order]
